internal void EndPaint(Graphics g, int meshId = -1)
		{
			if (!g.IsRenderGUIMode())
			{
				if (meshId != -1)
				{
					if (g.meshManList_[meshId] != null)
					{
						g.meshManList_[meshId].EndMesh();
					}
				}
				else
				{
					for (int i = 0; i < g.meshManList_.Length; i++)
					{
						if (g.meshManList_[i] != null)
						{
							g.meshManList_[i].EndMesh();
						}
					}
				}
				MeshManager[] meshManList_ = g.meshManList_;
				for (int j = 0; j < meshManList_.Length; j++)
				{
					foreach (MeshBuilder value in meshManList_[j].meshList_.Values)
					{
						foreach (MeshBuilder.Layer value2 in value.layers.Values)
						{
							foreach (MeshBuilder.Group group in value2.groups)
							{
								group.change = false;
							}
						}
					}
				}
			}
			g.EndGLRender(true);
			if (g == graphics_ && graphics_ != null)
			{
				graphics_.Dispose(true);
				graphics_ = null;
			}
			isAlterStaticRendering_ = false;
		}

public virtual void Draw(kairo.unity.ui.Graphics g)
		{
			bool flag = IsAutoGLRender();
			for (int i = 0; i < surfaceList_.Size(); i++)
			{
				g.ResetRender();
				if (flag)
				{
					g.BeginGLRender(autoGLRenderClipEnable_);
				}
				surfaceList_.ElementAt(i).OnDraw(g);
				if (flag)
				{
					g.EndGLRender();
				}
			}
			if (!Config.DEBUG || surfaceList_.Size() <= 0 || paintRects_.Count <= 0)
			{
				return;
			}
			SurfaceBase surfaceBase = surfaceList_.FirstElement();
			g.SetRenderRect(surfaceBase.GetX(), surfaceBase.GetY(), surfaceBase.GetWidth(), surfaceBase.GetHeight());
			g.Scale(surfaceBase.GetScaleRatio());
			try
			{
				float x = (Input.mousePosition.x - (float)surfaceBase.GetX()) * 100f / surfaceBase.GetScaleRatio();
				float y = ((float)Screen.height - Input.mousePosition.y - (float)surfaceBase.GetY()) * 100f / surfaceBase.GetScaleRatio();
				int rectIndex;
				int handleIndex;
				GetSelectPaintPoint(x, y, out rectIndex, out handleIndex);
				for (int j = 0; j < paintRects_.Count; j++)
				{
					int[] paintRect = GetPaintRect(paintRects_[j]);
					g.SetColor(255, 0, 0);
					g.DrawRect2(paintRect[0] - 1, paintRect[1] - 1, paintRect[2] + 2, paintRect[3] + 2);
					if (currentPaintRect_ != j && (Input.GetKey(KeyCode.LeftShift) || Input.GetKey(KeyCode.RightShift)))
					{
						Vector2[] paintHandlePoint = GetPaintHandlePoint(paintRects_[j]);
						for (int k = 0; k < paintHandlePoint.Length; k++)
						{
							g.SetColor(255, 150, 255);
							if (currentPaintRect_ == -1 && rectIndex == j && handleIndex == k)
							{
								g.SetColor(255, 255, 255);
							}
							g.FillRect(paintHandlePoint[k].x - 0.5f, paintHandlePoint[k].y - 0.5f, 2f, 2f);
						}
					}
					g.PushFont(6);
					int height = g.GetFont().GetHeight();
					string text = paintRect[0] + "," + paintRect[1];
					int num = paintRect[0];
					int num2 = paintRect[1] - 1 - height;
					if (num2 < 0)
					{
						num2 = 0;
					}
					g.SetColor(0, 0, 0, 150);
					g.FillRect((float)num - 0.5f, (float)num2 - 0.5f, g.StringWidth(text) + 1, height + 1);
					g.SetColor(255, 255, 255);
					g.DrawString(text, num, num2);
					text = paintRect[2] + "x" + paintRect[3];
					num = paintRect[0] + paintRect[2] - g.StringWidth(text);
					num2 = paintRect[1] + paintRect[3] + 1;
					if ((float)(num2 + height) > (float)(surfaceBase.GetHeight() * 100) / surfaceBase.GetScaleRatio())
					{
						num2 = (int)((float)(surfaceBase.GetHeight() * 100) / surfaceBase.GetScaleRatio() - (float)height);
					}
					g.SetColor(0, 0, 0, 150);
					g.FillRect((float)num - 0.5f, (float)num2 - 0.5f, g.StringWidth(text) + 1, height + 1);
					g.SetColor(255, 255, 255);
					g.DrawString(text, num, num2);
					g.PopFont();
				}
			}
			finally
			{
				g.Scale(100f);
				g.ClearRenderRect();
			}
		}

public Matrix PostConcat(float[] transform)
		{
			if (transform == null)
			{
				throw new NullReferenceException();
			}
			for (int i = 0; i < mul_.Length; i++)
			{
				mul_[i] = 0f;
			}
			for (int j = 0; j < 3; j++)
			{
				for (int k = 0; k < 3; k++)
				{
					mul_[j * 3 + k] = 0f;
					for (int l = 0; l < 3; l++)
					{
						mul_[j * 3 + k] += mtx_[j * 3 + l] * transform[l * 3 + k];
					}
				}
			}
			SetValues(mul_);
			return this;
		}

public void DrawString(TextFormat lf, string str, float x, float y, int anchor)
		{
			str = Language.TranslateText(str);
			if ((PeekAutoTextLayout() && str.IndexOf('<') != -1) || (lineSpacing_ != 0 && str.IndexOf('\n') != -1))
			{
				DrawString2(str, x, y, anchor);
				return;
			}
			int num = -1;
			if (!Language.Japanese() && lf != null)
			{
				if (lf.GetFont() != -1 && lf.GetFont() != font_.GetSize())
				{
					num = font_.GetSize();
					font_.SetSize(lf.GetFont());
				}
				x = lf.GetX(x);
				y = lf.GetY(y);
				anchor = lf.GetAnchor(anchor);
			}
			bool flag = (lf == null || lf.GetFont() == -1) && font_.IsNeedLocalizeScale();
			if (flag)
			{
				num = font_.GetSize();
				int height = font_.GetHeight();
				font_.SetSize(font_.GetLocalizeScale());
				if ((anchor & 0x60) == 0)
				{
					y += (float)(height - font_.GetHeight()) / 2f;
				}
				Font.LockLocalizeSetting();
			}
			BeginRenderMatrix(ref x, ref y);
			try
			{
				float num2;
				float num3;
				float num4;
				if (!isGUI_)
				{
					if (render_ != null)
					{
						Font font = new Font(GetFont());
						RectangleF transRectGUI = GetTransRectGUI(0f, 0f, font.GetWidth(), font.GetHeight(), DrawString_tmp);
						num2 = transRectGUI.Width() / font.GetWidth();
						num3 = transRectGUI.Height() / (float)font.GetHeight();
						num4 = ((num2 < num3) ? num2 : num3);
						font.SetSize((int)((float)font.GetHeight() * num4), false);
						y += ((float)font.GetHeight() - (float)font.GetHeight() * num4 / num3) / 2f;
						render_.textRenderTasks_.Add(new Image.TextRenderTask(str, x, y, anchor, color_, font));
					}
					return;
				}
				if ((anchor & 2) != 0)
				{
					x -= font_.StringWidthF(str) / 2f;
				}
				else if ((anchor & 4) != 0)
				{
					x -= font_.StringWidthF(str);
				}
				if ((anchor & 0x20) != 0)
				{
					y -= (float)font_.GetHeight() / 2f;
				}
				else if ((anchor & 0x40) != 0)
				{
					y -= (float)font_.GetHeight();
				}
				else if (fontScaleOffsetEnable_)
				{
					int height2 = font_.GetHeight();
					y += (float)((height2 * 100 / font_.fontScale_ - height2) / 2);
				}
				font_.GetHeight();
				font_.GetWidth();
				RectangleF transRectGUI2 = GetTransRectGUI(0f, 0f, font_.GetWidth(), font_.GetHeight(), DrawString_tmp);
				num2 = transRectGUI2.Width() / font_.GetWidth();
				num3 = transRectGUI2.Height() / (float)font_.GetHeight();
				num4 = ((num2 < num3) ? num2 : num3);
				guiStyle_.font = font_.GetFont();
				guiStyle_.fontSize = (int)((float)font_.GetHeight() * num4);
				guiStyle_.fontStyle = font_.GetFontStyle();
				y += ((float)font_.GetHeight() - (float)font_.GetHeight() * num4 / num3) / 2f;
				if (GUI.skin.font != guiStyle_.font)
				{
					GUI.skin.font = guiStyle_.font;
				}
				float[] transPointGUI = GetTransPointGUI(x, y, DrawString_tmp2);
				Color textColor = guiStyle_.normal.textColor;
				if (renderOperator_ == 0 && renderSrcRatio_ < 255)
				{
					Color textColor2 = guiStyle_.normal.textColor;
					textColor2.r = textColor2.r * (float)renderSrcRatio_ / 255f;
					textColor2.g = textColor2.g * (float)renderSrcRatio_ / 255f;
					textColor2.b = textColor2.b * (float)renderSrcRatio_ / 255f;
					guiStyle_.normal.textColor = textColor2;
				}
				else if (renderOperator_ == 1 && renderSrcRatio_ < 255)
				{
					Color textColor3 = guiStyle_.normal.textColor;
					textColor3.a = textColor3.a * (float)renderSrcRatio_ / 255f;
					guiStyle_.normal.textColor = textColor3;
				}
				if (glRender_)
				{
					if (glTextCount_ >= glTextList_.Count)
					{
						glTextList_.Add(new GLText());
					}
					glTextList_[glTextCount_].Init(new Rect(transPointGUI[0], transPointGUI[1], 1f, transRectGUI2.Height() * 2f), str, guiStyle_, clipRegion_);
					glTextCount_++;
				}
				else
				{
					UpdateGUIGroup();
					GUI.Label(new Rect(transPointGUI[0], transPointGUI[1], 1f, transRectGUI2.Height() * 2f), str, guiStyle_);
				}
				guiStyle_.normal.textColor = textColor;
				if (Config.COUNT_ENABLE)
				{
					Config.drawStringCount_++;
				}
			}
			finally
			{
				EndRenderMatrix();
				if (flag)
				{
					Font.UnlockLocalizeSetting();
				}
				if (num != -1)
				{
					font_.SetSize(num);
				}
			}
		}
